// Normalizza il lead e prepara l'evento per la Conversions API di Meta.
// Richiede NODE_FUNCTION_ALLOW_BUILTIN=crypto nelle variabili di n8n.
const crypto = require('crypto');
const sha = (v) => (v ? crypto.createHash('sha256').update(v).digest('hex') : undefined);
const b = $json.body ?? $json;
const email = String(b.email ?? '').trim().toLowerCase();
let phone = String(b.phone ?? '').replace(/\D/g, '');
if (phone && phone.length <= 10) phone = '39' + phone; // numeri italiani senza prefisso
const [fn, ...rest] = String(b.name ?? '').trim().toLowerCase().split(/\s+/);
const user_data = {
  em: email ? [sha(email)] : undefined,
  ph: phone ? [sha(phone)] : undefined,
  fn: fn ? [sha(fn)] : undefined,
  ln: rest.length ? [sha(rest.join(' '))] : undefined,
  country: [sha('it')],
  client_user_agent: b.user_agent || undefined,
  client_ip_address: $json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || undefined,
  fbp: b.fbp || undefined,
  fbc: b.fbc || undefined,
};
return [{ json: {
  lead: b,
  marketing_consent: b.marketing_consent === true,
  capi: { data: [{
    event_name: 'Lead',
    event_time: Number(b.event_time) || Math.floor(Date.now() / 1000),
    event_id: b.event_id,
    action_source: 'website',
    event_source_url: b.page_url,
    user_data,
    custom_data: { content_name: b.source },
  }] },
} }];
